function Test-ControlProgressAgreement($Progress,$Rows) {
 try {
  if($Progress -isnot [Collections.IDictionary] -or (($Progress.Keys|Sort-Object)-join '|') -cne 'assertion|case|completed|valid'){return $false}
  if($Progress.valid -isnot [bool] -or -not $Progress.valid -or $Progress.case -isnot [string] -or $Progress.assertion -isnot [int] -or $Progress.assertion -ne 40){return $false}
  if($Progress.completed -isnot [object[]] -or $Progress.completed.Rank -ne 1 -or $Progress.completed.GetLowerBound(0) -ne 0 -or $Progress.completed.Count -ne 6){return $false}
  if($Rows -isnot [object[]] -or $Rows.Rank -ne 1 -or $Rows.GetLowerBound(0) -ne 0 -or $Rows.Count -ne 6){return $false}
  for($i=0;$i -lt 6;$i++){
   $row=$Rows[$i]
   if($row -isnot [hashtable] -or (($row.Keys|Sort-Object)-join '|') -cne 'name|outcome' -or $row.name -isnot [string] -or $row.outcome -isnot [string] -or $row.outcome -cne 'PASS' -or $Progress.completed[$i] -isnot [string] -or $Progress.completed[$i] -cne $row.name){return $false}
  }
  if($Progress.case -cne $Rows[5].name){return $false}
  return $true
 }catch{return $false}
}
function Hash([string]$Path)

# BEGIN COMPLETE CONTROL PROGRESS ADMISSION
